@Injectable()
export class AlertService {
  public static async processOutboundAndAssignments(
    shopOrders: Array<AlertEscalateResponseDTO>,
    plantKey: number,
    shipmentApi: ShipmentApi,
  ): Promise<Array<AlertEscalateResponseDTO>> {
    const outbounds = AlertService.extractUniqueOutbounds(shopOrders);

    const tpaCodeRequestDto = AlertService.createTpaCodeRequestDto(
      plantKey,
      outbounds,
    );

    const tapaAssigmentArray =
      await shipmentApi.fetchTpaAssignmentDetail(tpaCodeRequestDto);

    if (!tapaAssigmentArray || tapaAssigmentArray.length === 0) {
      throw new Error('No TPA Assignment FOUND');
    }
    const tapaAssigment = tapaAssigmentArray[0] as Record<
      string,
      TpaAssignmentDetailsResponseDTO
    >;

    return AlertService.updateShopOrders(shopOrders, tapaAssigment);
  }

  private static extractUniqueOutbounds(
    shopOrders: Array<AlertEscalateResponseDTO>,
  ): Array<string> {
    return [
      ...new Set(shopOrders.map((order) => order?.outbound)),
    ] as Array<string>;
  }

  private static createTpaCodeRequestDto(
    plantKey: number,
    outbounds: Array<string>,
  ): TpaCodeRequestDto {
    const tpaCodeRequestDto = new TpaCodeRequestDto();
    tpaCodeRequestDto.plant = plantKey;
    tpaCodeRequestDto.outbound = outbounds;
    return tpaCodeRequestDto;
  }

  private static updateShopOrders(
    shopOrders: Array<AlertEscalateResponseDTO>,
    tapaAssigment: Record<string, TpaAssignmentDetailsResponseDTO>,
  ): Array<AlertEscalateResponseDTO> {
    const updatedShopOrders: Array<AlertEscalateResponseDTO> = [];

    for (const shopOrder of shopOrders) {
      const updatedShopOrder = { ...shopOrder };
      const assignment = tapaAssigment[shopOrder.outbound.toString()];
      if (assignment) {
        if (assignment.truckDeparture) {
          updatedShopOrder.truckDepartureTime = new Date(
            assignment.truckDeparture,
          );
        }
        if (assignment.endPrep) {
          updatedShopOrder.endPreparationTime = new Date(assignment.endPrep);
        }

        updatedShopOrder.alertEscalateLevel =
          AlertService.updateShopOrderAlertLevel(updatedShopOrder);
      }
      updatedShopOrders.push(updatedShopOrder);
    }

    return updatedShopOrders;
  }

  private static updateShopOrderAlertLevel(
    shopOrder: AlertEscalateResponseDTO,
  ): string {
    const updatedShopOrder = { ...shopOrder };
    const newPickingTime = new Date(updatedShopOrder.newPickingTime);
    if (
      updatedShopOrder.endPreparationTime &&
      newPickingTime < updatedShopOrder.endPreparationTime
    ) {
      return 'YELLOW';
    }
    if (
      updatedShopOrder.truckDepartureTime &&
      newPickingTime < updatedShopOrder.truckDepartureTime
    ) {
      return 'ORANGE';
    }
    return 'RED';
  }

  private static buildShopOrdersXml(
    updatedShopOrders: Array<AlertEscalateResponseDTO>,
  ): string | null {
    if (!updatedShopOrders || updatedShopOrders.length === 0) {
      return null;
    }
    const builder = new xml2js.Builder({ rootName: 'Rowsets' });
    // Wrap single object into array, if needed
    const wrappedData =
      updatedShopOrders.length === 1 ? [updatedShopOrders] : updatedShopOrders;

    return builder.buildObject({
      rowset: { row: wrappedData },
    });
  }

  private static async getSecretValue(
    client: DaprClient,
    store: string,
    name: string,
  ): Promise<string> {
    const secret = await client.secret.get(store, name);
    return Object.values(secret)[0];
  }

  public static async extractEscalationSummaryFromXml(
    xmlString: string,
  ): Promise<Array<AlertSmsFlagUpdateDto>> {
    if (!xmlString) return [];
    try {
      const parsed = await parseStringPromise(xmlString, {
        explicitArray: false,
      });
      const rows = parsed?.Rowsets?.rowset?.row;
      if (!rows) return [];
      const rowArray = Array.isArray(rows) ? rows : [rows];
      return rowArray
        .map((row) => {
          const plant = Number(row.plant);
          const alertId = Number(row.alertId);
          const { alertEscalateLevel } = row;
          if (
            !Number.isNaN(plant) &&
            !Number.isNaN(alertId) &&
            typeof alertEscalateLevel === 'string' &&
            alertEscalateLevel
          ) {
            return { plant, alertId, alertEscalateLevel };
          }
          return null;
        })
        .filter(Boolean) as Array<AlertSmsFlagUpdateDto>;
    } catch {
      return [];
    }
  }

