  public async automaticAlertCreation(
    plant: number,
  ): Promise<AutomaticAlertCreationResponse> {
    const autoAlertWorkcenters =
      await this.orderApi.isAlertCreationAutomaticWC(plant);
    if (autoAlertWorkcenters?.length === 0 || !autoAlertWorkcenters) {
      return { failed: 0, success: 0 };
    }
    const data = await this.orderApi.getPickingOrdersRequiringAlert(
      plant,
      autoAlertWorkcenters,
    );
    const initialShopOrders = data.shopOrders;
    const { dateNow } = data;
    if (initialShopOrders.length === 0) {
      return { failed: 0, success: 0 };
    }

    const workcenters = [
      ...new Set(initialShopOrders.map((order) => order?.workcenter)),
    ];
    const adavancepickingDuration =
      await this.getAdvancePickingDurationsByWorkcentersAndPlant(
        plant,
        workcenters,
      );
    // Map advancePickingDuration to a dictionary for quick lookup by workcenter
    const advancePickingDurationMap: Record<string, number> = {};

    for (const item of adavancepickingDuration) {
      const { workcenterId, advancePickingDuration } = item;
      advancePickingDurationMap[workcenterId] = Number(advancePickingDuration);
    }

    // Filter shopOrders based on the condition
    const filteredShopOrders = initialShopOrders.filter((order) => {
      const advanceDuration = advancePickingDurationMap[order.workcenter];

      // Calculate the new planned start date + advance picking duration
      const plannedStartDate = new Date(order.plannedStartDate);
      const plannedStartDateWithAdvance =
        plannedStartDate.getTime() + advanceDuration * 60_000; // Convert minutes to ms
      return plannedStartDateWithAdvance < new Date(dateNow).getTime();
    });
    if (filteredShopOrders.length === 0) {
      return { failed: 0, success: 0 };
    }

    const shopOrders = await updateWorkcentersForSfgUseCase(
      String(plant),
      filteredShopOrders,
      this.orderApi,
    );
    const updatedWorkcenters = [
      ...new Set(shopOrders.map((order) => order?.workcenter)),
    ];
    const alertConfigIds =
      (await this.orderApi.getAlertConfigByPlantAndWorkcenters(
        Number(plant),
        updatedWorkcenters,
      )) as Record<string, AlertConfigResponseDto>;
    if (!alertConfigIds) {
      await this.storedLogger.functionalLog(
        {
          applicationName: 'picking-be',
          context: {
            workcenterIds: updatedWorkcenters,
          },
          errorCode: ERROR_CODES.missingAlertConfig.code,
          objectId: `${plant}`,
          plant,
          user: 'SYSTEM-JOB',
        },
        { usefireAndForget: true },
      );
      throw new NotFoundException('Alert Config Not Found');
    }
    const resources = (await this.plantHYRApi.getResourceDetailsByWcIds(
      Number(plant),
      workcenters,
    )) as Record<string, ResourceResponseDTO>;
    const root = create().ele('Rowsets');
    const rowset = root.ele('Rowset');
    let resource = '';
    for (const shopOrder of shopOrders) {
      if (resources) {
        resource = resources[shopOrder.workcenter]?.resourceId || '';
      }
      const validation = createAlertValidation(shopOrder, alertConfigIds);
      if (!validation) {
        const row = rowset.ele('Row');
        row
          .ele('ALERT_CONFIG_ID')
          .txt(String(alertConfigIds[shopOrder.workcenter].alertConfigId));
        row.ele('MATERIAL').txt(shopOrder.material);
        row.ele('PICKING_ORDER_ID').txt(shopOrder.pickingOrderId);
        row.ele('WORKCENTER').txt(shopOrder.workcenter);
        row.ele('RESOURCE_ID').txt(resource);
        row.ele('ALERT_SOURCE').txt('AUTOMATIC');
        root.end({ prettyPrint: true });
      }
    }

    const xmlString = root.end({ prettyPrint: true });

    if (xmlString.includes('<Rowset/>')) {
      return { failed: 0, success: 0 };
    }

    const daprClient = new DaprClient();
    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(Number(plant));

    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      await this.storedLogger.functionalLog(
        {
          applicationName: 'picking-be',
          errorCode: ERROR_CODES.incompleteApiManager.code,
          objectId: `${plant}`,
          plant,
          user: 'SYSTEM-JOB',
        },
        { usefireAndForget: true },
      );
      throw new Error('API Manager setup is incomplete');
    }
    return this.handleCreateAlertRequest(
      plant,
      root,
      apiMgrKeyValue,
      mesPasswordValue,
      writeBackUrl,
    );
  }

  private async handleCreateAlertRequest(
    plantKey: number,
    root: XMLBuilder,
    apiMgrKeyValue: string,
    mesPasswordValue: string,
    writeBackUrl: string,
  ): Promise<AutomaticAlertCreationResponse> {
    try {
      const formData = new URLSearchParams();
      formData.append('listWksXml', root.toString());
      const headersDto = new RequestHeadersDto(
        'application/x-www-form-urlencoded',
        apiMgrKeyValue,
      );
      const parameters = new AlertConfigRequestDto(
        Number(plantKey),
        'text/json',
        'ResultXML',
        'SC_MES_API/INTERFACE/ALERT/V1/XCT_CREATE_ALERT',
        false,
        `${await this.apiManagerConfigService.mesUserName()}`,
        `${mesPasswordValue}`,
      );
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, formData, {
          headers: { ...headersDto },
          params: parameters,
        }),
      );
      const jsonData = response.data;
      const rows = jsonData?.Rowsets?.Rowset[0]?.Row;
      const statusSummary = { failed: 0, success: 0 };

      for (const item of rows) {
        const statusCode = String(item['STATUS_CODE']).toLowerCase();
        if (statusCode === 'error') {
          statusSummary.failed += 1;
        } else {
          statusSummary.success += 1;
        }
      }
      return statusSummary;
    } catch (error) {
      await this.storedLogger.functionalLog({
        applicationName: 'picking-be',
        context: {
          method: 'handleCreateAlertRequest',
          error,
        },
        errorCode: ERROR_CODES.unexpectedError.code,
        objectId: `${plantKey}`,
        plant: plantKey,
        user: 'SYSTEM-JOB',
      });
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          'An unexpected error occurred MII',
        );
      }
      throw error;
    }
  }

