  public readonly daprClient: DaprClient;

  public constructor(public readonly httpService: HttpService) {
    this.daprClient = new DaprClient();
  }

  public async getPlantById(plantId: number): Promise<unknown> {
    const serviceAppId = 'plt-hry-api';
    const serviceMethodPlant = `plant/getPlantById/${plantId}`;
    const response = await this.daprClient.invoker
      .invoke(serviceAppId, serviceMethodPlant, HttpMethod.GET)
      .catch((error) => this.logger.error(error));
    if (response) {
      return response;
    }
    throw new Error('Invalid response from getPlantById');
  }
}

