import { Logger } from '@nestjs/common';
import pLimit from 'p-limit';

export class ChunkProcess {
  public static async processInChunksArray<T, TResult>(
    items: Array<T>,
    chunkSize: number,
    processChunk: (chunk: Array<T>) => Promise<Array<TResult>>,
    sortFunction?: (a: T, b: T) => number,
    concurrencyLimit = 5, // Optional limit
  ): Promise<Array<TResult>> {
    const limit = pLimit(concurrencyLimit);
    const chunkPromises: Array<Promise<Array<TResult>>> = [];
    if (sortFunction) {
      items.sort(sortFunction);
    }
    for (let index = 0; index < items.length; index += chunkSize) {
      const chunk = items.slice(index, index + chunkSize);
      chunkPromises.push(
        limit(() =>
          processChunk(chunk).catch((error) => {
            Logger.error(`Error processing chunk at index ${index}: ${error}`);
            return [];
          }),
        ),
      );
    }
    const chunkResults = await Promise.all(chunkPromises);
    return chunkResults.flat();
  }
}

import { DateTime } from 'luxon';

/**
 * Converts a date from a specific timezone to UTC.
 * @param date - The date to convert, as a string in ISO format or a Date object.
 * @param timezone - The timezone of the input date.
 * @returns A Date object in UTC.
 * @throws Will throw an error if the date is invalid.
 */
export function convertToUTC(date: string | Date, timezone: string): Date {
  let dateTime: DateTime;
  let utcDate: Date;

  if (typeof date === 'string') {
    const sourceDateTime = DateTime.fromISO(date, { zone: timezone });
    dateTime = sourceDateTime
      .toUTC()
      .minus({ milliseconds: sourceDateTime.offset * 60_000 });
  } else {
    const sourceDateTime = DateTime.fromJSDate(date, { zone: timezone });
    dateTime = sourceDateTime
      .toUTC()
      .minus({ milliseconds: sourceDateTime.offset * 60_000 });
  }
  const utcDateString = dateTime.toISO();
  if (!utcDateString) {
    throw new Error('Invalid date format');
  }

  utcDate = new Date(utcDateString);
  utcDate = new Date(utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000);

  return utcDate;
}
/**
 * Converts a date from UTC to a specific timezone.
 * @param date - The date in UTC to convert.
 * @param timezone - The target timezone.
 * @returns The date in the specified timezone.
 */
export function convertFromUTC(date: string | Date, timezone: string): string {
  const dateTime =
    typeof date === 'string'
      ? DateTime.fromISO(date, { zone: 'utc' })
      : DateTime.fromJSDate(date, { zone: 'utc' });

  if (!dateTime.isValid) {
    throw new Error('Invalid date format');
  }

  return dateTime.setZone(timezone).toFormat('yyyy-MM-dd HH:mm:ss.SSS');
}

/**
 *
 * @param date
 * @param timezone
 */
export function getDayInterval(
  date: string,
  timezone: string,
): { start: string; end: string } {
  if (!date || !timezone) {
    throw new Error('Date and timezone must be provided.');
  }

  const parsedDate = DateTime.fromISO(date, { zone: timezone });
  if (!parsedDate.isValid) {
    throw new Error(
      `Invalid date or timezone. Date: ${date}, Timezone: ${timezone}`,
    );
  }

  return {
    start: parsedDate.startOf('day').toUTC().toISO() || '',
    end: parsedDate.endOf('day').toUTC().toISO() || '',
  };
}

import { DateTime } from 'luxon';
import { PickingQueryParameters } from '@/picking/interfaces/picking-query-parameters';

// Your existing filter function
/**
 *@returns string
 * @param queryParameters // query parameters needed for filter
 */
function addPickingTimeFilter(queryParameters: PickingQueryParameters): string {
  const { pickingTimeScale, pickingTimeMin, pickingTimeMax } = queryParameters;
  if (pickingTimeScale && pickingTimeMin && pickingTimeMax) {
    const now = DateTime.utc();
    let scale: 'weeks' | 'days' | 'hours';

    switch (pickingTimeScale) {
      case 'weeks':
      case 'days':
      case 'hours': {
        scale = pickingTimeScale;
        break;
      }
      default: {
        throw new Error('Invalid pickingTimeScale');
      }
    }

    const minTime = now.minus({ [scale]: pickingTimeMin }).toISO();
    const maxTime = now.plus({ [scale]: pickingTimeMax }).toISO();
    return `((c.pickingTime >= '${minTime}' AND c.pickingTime <= '${maxTime}') OR (c.newPromiseTime >= '${minTime}' AND c.newPromiseTime <= '${maxTime}'))`;
  }

  return '';
}

// The validator function
/**
 * @param queryParameters // query parameters needed for filter
 * @returns boolean
 */
function validatePickingTimeRange(
  queryParameters: PickingQueryParameters,
): boolean {
  const { pickingTimeScale, pickingTimeMin, pickingTimeMax } = queryParameters;

  if (!pickingTimeScale || !pickingTimeMin || !pickingTimeMax) return false;

  const min = pickingTimeMin;
  const max = pickingTimeMax;
  switch (pickingTimeScale) {
    case 'hours': {
      return min >= 0 && min <= 24 && max >= 0 && max <= 24;
    }
    case 'days': {
      return min >= 0 && min <= 7 && max >= 0 && max <= 7;
    }
    case 'weeks': {
      return min >= 0 && min <= 2 && max >= 0 && max <= 4;
    }
    default: {
      return false;
    }
  }
}

// Wrapper that combines validation and filter generation
/**
 * @param queryParameters // query parameters needed for filter
 *  @returns string
 */
function buildPickingTimeQuery(
  queryParameters: PickingQueryParameters,
): string {
  if (validatePickingTimeRange(queryParameters)) {
    return addPickingTimeFilter(queryParameters);
  }
  throw new Error(
    'Invalid picking time range. Ensure that min and max values are within allowed limits.',
  );
}

/**
 *
 * @param queryParameters // query parameters needed for filter
 * @param filterConditions // filtering condition needed
 */
export function addRescheduledFilter(
  queryParameters: PickingQueryParameters,
  filterConditions: Array<string>,
): void {
  const { rescheduled } = queryParameters;

  if (rescheduled) {
    let condition: string;

    switch (rescheduled.toLowerCase()) {
      case 'yes': {
        // Rescheduled: new promise time exists and is not null
        condition = `(IS_DEFINED(c.newPromiseTime) AND NOT IS_NULL(c.newPromiseTime))`;
        break;
      }
      case 'no': {
        // Not rescheduled: new promise time is null (or missing)
        // Parentheses are critical here since this condition contains OR.
        condition = `((NOT IS_DEFINED(c.newPromiseTime)) OR IS_NULL(c.newPromiseTime))`;
        break;
      }
      default: {
        condition = ''; // No filter for '*'
        break;
      }
    }

    if (condition) {
      filterConditions.push(condition);
    }
  }
  if (queryParameters.pickingTimeScale) {
    const pickingTimeCondition = buildPickingTimeQuery(queryParameters);
    if (pickingTimeCondition) {
      filterConditions.push(pickingTimeCondition);
    }
  }
}

/**
 *
 * @param queryParameters // query parameters needed for filter
 * @param filterConditions // filtering condition needed
 */
export function addalertFilter(
  queryParameters: PickingQueryParameters,
  filterConditions: Array<string>,
): void {
  const { alert } = queryParameters;

  if (alert) {
    let condition: string;

    switch (alert.toLowerCase()) {
      case 'yes': {
        condition = `c.alertCreated = true`;
        break;
      }
      case 'no': {
        condition = `c.alertCreated = false`;
        break;
      }
      default: {
        condition = ''; // No filter for '*'
        break;
      }
    }

    if (condition) {
      filterConditions.push(condition);
    }
  }
}

/**
 *
 * @param queryParameters // the parameters that needed to filter
 * @param filterConditions // the filters condition needed
 * @param queryParametersList // the list of parameters
 */
export function addDateFilters(
  queryParameters: PickingQueryParameters,
  filterConditions: Array<string>,
  queryParametersList: Array<{
    name: string;
    value: string | number | boolean;
  }>,
): void {
  const {
    endProductionTime,
    endProdTimeType,
    tpaBeginPreparation,
    startPrepTimeType,
    tpaEndPreparation,
    endPrepTimeType,
    truckDepartureTime,
    truckDepartureType,
    promiseTime, // Specific mode by default
  } = queryParameters;

  const nowUTC = new Date().toISOString();

  const handleDateFilter = (
    dateValue: string | undefined,
    dateType: string | undefined,
    fieldName: string,
    parameterName: string,
  ): void => {
    if (dateValue || dateType) {
      let condition: string;
      const now = `@now_${parameterName}`;

      switch (dateType) {
        case 'Specific': {
          if (!dateValue) {
            throw new Error(`Expected a valid dateValue for ${parameterName}`);
          }

          // Convert dateValue to UTC
          const dateValueUTC = new Date(dateValue).toISOString();

          // Set the start to dateValueUTC
          const startUTC = dateValueUTC; // Start is the original dateValueUTC

          // Add 24 hours to dateValueUTC to get the end date
          const dateValueObject = new Date(dateValueUTC);
          dateValueObject.setHours(dateValueObject.getHours()); // Add 24 hours

          // Set the end time to the last millisecond of the next day (23:59:59.999)
          const endDateUTC = new Date(dateValueObject);
          endDateUTC.setDate(endDateUTC.getDate() + 1); // Add 1 day (24 hours)
          // Convert the end date to ISO format
          const endUTC = endDateUTC.toISOString();
          // Build the condition
          condition = `c.${fieldName} >= @${parameterName}Start AND c.${fieldName} < @${parameterName}End`;

          // Push the parameters to the query
          queryParametersList.push(
            { name: `@${parameterName}Start`, value: startUTC },
            { name: `@${parameterName}End`, value: endUTC },
          );
          break;
        }

        case 'Future': {
          if (!dateValue) {
            throw new Error(`Expected a valid dateValue for ${parameterName}`);
          }
          const dateValueUTC = new Date(dateValue).toISOString();
          condition = `c.${fieldName} >= ${now} AND c.${fieldName} <= @${parameterName}`;
          queryParametersList.push(
            { name: now, value: nowUTC },
            { name: `@${parameterName}`, value: dateValueUTC },
          );
          break;
        }

        case 'Past': {
          condition = `c.${fieldName} < ${now}`;
          queryParametersList.push({ name: now, value: nowUTC });
          break;
        }

        case 'All': {
          condition = '1=1'; // No filtering condition
          break;
        }
        default: {
          condition = '1=1';
          break;
        }
      }

      filterConditions.push(condition);
    }
  };

  // Handle promiseTime as "Specific" by default
  if (promiseTime) {
    const dateValueUTC = new Date(promiseTime).toISOString();

    // Set the start to dateValueUTC
    const startUTC = dateValueUTC; // Start is the original dateValueUTC

    // Add 24 hours to dateValueUTC to get the end date
    const dateValueObject = new Date(dateValueUTC);
    dateValueObject.setHours(dateValueObject.getHours()); // Add 24 hours

    // Set the end time to the last millisecond of the next day (23:59:59.999)
    const endDateUTC = new Date(dateValueObject);
    endDateUTC.setDate(endDateUTC.getDate() + 1); // Add 1 day (24 hours)
    // Convert the end date to ISO format
    const endUTC = endDateUTC.toISOString();

    // Convert the end date to ISO format
    const condition = `
      EXISTS (
        SELECT VALUE history
        FROM history IN c.reschedulerWkHistories
        WHERE history.newPickingTime >= '${startUTC}' AND history.newPickingTime <= '${endUTC}'
      )
    `;
    filterConditions.push(condition);
  }

  // Handle other date filters
  handleDateFilter(
    endProductionTime,
    endProdTimeType,
    'endProductionTime',
    'endProdDate',
  );
  handleDateFilter(
    tpaBeginPreparation,
    startPrepTimeType,
    'tpaBeginPreparation',
    'startPrepDate',
  );
  handleDateFilter(
    tpaEndPreparation,
    endPrepTimeType,
    'tpaEndPreparation',
    'endPrepDate',
  );
  handleDateFilter(
    truckDepartureTime,
    truckDepartureType,
    'truckDepartureTime',
    'truckDepDate',
  );
}
/**
 *
 * @param queryParameters // the parameters that needed to filter
 * @param filterConditions // the filters condition needed
 * @param queryParametersList // the list of parameters
 */
export function addFiltersForQueryParameters(
  queryParameters: PickingQueryParameters,
  filterConditions: Array<string>,
  queryParametersList: Array<{
    name: string;
    value: string | number | boolean;
  }>,
): void {
  // Define keys to exclude
  const excludedKeys = new Set([
    'endProductionTime',
    'endProdTimeType',
    'tpaBeginPreparation',
    'startPrepTimeType',
    'tpaEndPreparation',
    'endPrepTimeType',
    'truckDepartureTime',
    'truckDepartureType',
    'promiseTime',
    'rescheduled',
    'alert',
    'pickingStatus',
    'pickingTimeScale',
    'pickingTimeMin',
    'pickingTimeMax',
  ]);

  // Process general fields
  for (const key of Object.keys(queryParameters)) {
    if (!excludedKeys.has(key)) {
      const frontendKey = key as keyof PickingQueryParameters;
      const value = queryParameters[frontendKey];

      if (value) {
        let condition: string | null;
        let formattedValues: Array<string> = [];
        condition = null as unknown as string;

        if (typeof value === 'string') {
          formattedValues = value.split(',').map((v) => `'${v.trim()}'`);
        } else if (Array.isArray(value)) {
          formattedValues = value.map((v) => `'${v}'`);
        }

        if (formattedValues.length === 1) {
          condition = `c.${frontendKey} = ${formattedValues[0]}`;
        } else if (formattedValues.length > 1) {
          condition = `c.${frontendKey} IN (${formattedValues.join(', ')})`;
        }

        if (condition) {
          filterConditions.push(condition);
        }
      }
    }
  }

  addRescheduledFilter(queryParameters, filterConditions);
  addalertFilter(queryParameters, filterConditions);

  // Handle date-related filters
  addDateFilters(queryParameters, filterConditions, queryParametersList);
}

import { ShopOrder } from '../dto/shop-order-dto';
import { OrderApi } from '@/common/api/order.api';

const NOT_SFG_STATUSES = new Set([
  'SFG_PIK_CLOSED',
  'PICKED',
  'PIK_CLOSED',
  'PALLETIZED',
  'OPEN',
  'TAKE_FROM_STOCK',
]);
/**
 * Filters shop orders by SFG-related statuses, updates their workcenter
 * based on data fetched from the OrderApi, and returns the combined list.
 * @param plantKey - The plant identifier used for querying workcenters.
 * @param shopOrders - The array of ShopOrder objects to process.
 * @param orderApi - The OrderApi instance used to fetch updated workcenters.
 * @returns A Promise resolving to an array of ShopOrders with updated workcenters.
 */
export async function updateWorkcentersForSfgUseCase(
  plantKey: string,
  shopOrders: Array<ShopOrder>,
  orderApi: OrderApi,
): Promise<Array<ShopOrder>> {
  const sfgOrders: Array<ShopOrder> = [];
  const otherOrders: Array<ShopOrder> = [];

  for (const order of shopOrders) {
    if (NOT_SFG_STATUSES.has(order.customStatus)) {
      otherOrders.push(order);
    } else {
      sfgOrders.push(order);
    }
  }
  const pickingOrderIds = sfgOrders.map((o) => o.pickingOrderId);
  if (pickingOrderIds.length === 0) {
    return shopOrders; // No SFG orders to process, return original list
  }
  const workcenterMap = await orderApi.getWorkcentersByPlantAndPickingOrderIds(
    plantKey,
    pickingOrderIds,
  );
  for (const order of sfgOrders) {
    const updatedWorkcenter = workcenterMap[order.pickingOrderId];
    if (updatedWorkcenter) {
      order.workcenter = updatedWorkcenter;
    }
  }

  return [...sfgOrders, ...otherOrders];
}

import { AlertConfigResponseDto } from '../dto/alert-config-response-dto';
import { ShopOrder } from '../dto/shop-order-dto';
import { WriteBackResponse } from '../dto/write-back-response-dto';

/**
 * Creates alert validation based on shop order, alert configurations, and resources.
 * @param shopOrder - The shop order for which alerts are validated.
 * @param alertConfigIds - A record of alert configuration IDs.
 * @returns The validation response or undefined if no alerts are generated.
 */
export function createAlertValidation(
  shopOrder: ShopOrder,
  alertConfigIds: Record<string, AlertConfigResponseDto>,
): Array<WriteBackResponse> | undefined {
  const responseArray: Array<WriteBackResponse> = [];
  const responseBack = new WriteBackResponse();

  if (shopOrder.alertCreated && shopOrder.alertStatus !== 'Closed') {
    responseBack.alertId = Number(shopOrder.alertId);
    responseBack.statusCode = 'FAILURE';
    responseBack.statusMessage = 'Alert already created on WK';
    responseBack.pickingOrderId = shopOrder.pickingOrderId;
    responseArray.push(responseBack);
    return responseArray;
  }

  if (!alertConfigIds[shopOrder.workcenter]?.alertConfigId) {
    responseBack.alertId = 0;
    responseBack.statusCode = 'FAILURE';
    responseBack.statusMessage = 'Alert configuration not found.';
    responseBack.pickingOrderId = shopOrder.pickingOrderId;
    responseArray.push(responseBack);
    return responseArray;
  }

  if (shopOrder.customStatus === 'PIK_CLOSED') {
    responseBack.alertId = 0;
    responseBack.statusCode = 'FAILURE';
    responseBack.statusMessage =
      'Alert cannot be created, WK Custom status is PIK_CLOSED ';
    responseBack.pickingOrderId = shopOrder.pickingOrderId;
    responseArray.push(responseBack);
    return responseArray;
  }
  return undefined;
}

/**
 * Validates if the given date string is valid.
 * @param date - The date string to validate.
 * @returns True if the date is valid, false if it contains '1900-' or '1899-'.
 */
export function validateDate(date: string): boolean {
  return !date.includes('1900-') && !date.includes('1899-');
}

/**
 * Checks and determines the appropriate alert status based on shop order timings.
 * @param item - The shop order containing timing details.
 * @param truckDepartureTime - The departure time of the truck in milliseconds.
 * @param currentDate - The current time in milliseconds.
 * @returns The alert status as a string ('ORANGE' or 'yellow').
 */
export function tpaEndPreparationChecks(
  item: ShopOrder,
  truckDepartureTime: number,
  currentDate: number,
): string | undefined {
  if (item.tpaEndPreparation && validateDate(item.tpaEndPreparation)) {
    const tpaEndPreparation = new Date(item.tpaEndPreparation).getTime();
    if (item.newPromiseTime && validateDate(item.newPromiseTime)) {
      const newPromiseTime = new Date(item.newPromiseTime).getTime();
      if (
        tpaEndPreparation < newPromiseTime &&
        newPromiseTime < truckDepartureTime &&
        truckDepartureTime > currentDate
      ) {
        return 'ORANGE';
      }
      if (newPromiseTime < tpaEndPreparation) {
        if (
          currentDate > tpaEndPreparation &&
          currentDate < truckDepartureTime
        ) {
          return 'ORANGE';
        }
        if (tpaEndPreparation > currentDate) {
          return 'YELLOW';
        }
      }
    } else if (
      currentDate > tpaEndPreparation &&
      currentDate < truckDepartureTime
    ) {
      return 'ORANGE';
    }
  }
  return undefined;
}

/**
 * Determines if the alert status should be 'WHITE' or 'GREY' based on the advance picking duration and picking time.
 * @param item - The shop order containing timing details.
 * @param currentDate - The current time in milliseconds.
 * @returns The alert status as a string ('WHITE' or 'GREY').
 */
export function whiteOrGreyCheck(item: ShopOrder, currentDate: number): string {
  let advanceDuration = 0;
  if (
    item.advancePickingDuration &&
    item.advancePickingDuration !== undefined &&
    item.advancePickingDuration !== null &&
    item.advancePickingDuration !== 'null'
  ) {
    const parsed = Number(item.advancePickingDuration);
    if (!Number.isNaN(parsed)) {
      advanceDuration = parsed;
    }
  }
  const pickingDate = new Date(item.pickingTime).getTime();
  const adjustedStartDate = pickingDate + advanceDuration * 60_000; // Adjust by picking duration

  return currentDate < adjustedStartDate ? 'WHITE' : 'GREY';
}

