@Injectable()
export class PickingService {
  private readonly logger = new AppLogger();

  private readonly customHttpService: HttpService;

  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  public constructor(
    private readonly orderApi: OrderApi,
    private readonly plantHYRApi: PlantHierarchyApi,
    private readonly cosmosConfigService: CosmosDatabaseConfigService,
    private readonly httpService: HttpService,
    private readonly apiManagerConfigService: ApiManagerConfigService,
    private readonly productionApi: ProductionApi,
  ) {
    const httpsAgent = new https.Agent({
      rejectUnauthorized: true, // Enforce SSL Certificate Verification
    });

    // Create a custom Axios instance using the custom HTTPS agent
    const axiosConfig: AxiosRequestConfig = {
      headers: this.httpService.axiosRef.defaults.headers as any, // Ensure headers are properly typed
      httpsAgent,
    };
    const customAxiosInstance = axios.create(axiosConfig);

    // Initialize a new HttpService with the custom Axios instance
    this.customHttpService = new HttpService(customAxiosInstance);

    // Create DefaultAzureCredential with the user-assigned managed identity's Client ID

    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosConfigService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosConfigService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosConfigService.cosmosDbContainer,
    );
  }

  public async create(plantId: string, pickingData: ShopOrder): Promise<void> {
    try {
      this.logger.debug(
        `Upserting single shop order with ${JSON.stringify(pickingData.pickingOrderId)}:`,
      );

      // Create the order object with necessary fields
      const orderWithId = {
        ...pickingData,
        id: pickingData.pickingOrderId,
        plant: Number(plantId),
      };

      // Upsert the single shop order
      await this.container.items.upsert(orderWithId);
      this.logger.debug(
        `Successfully upserted shop order with ID ${orderWithId.id}.`,
      );
    } catch (error) {
      this.logger.error(
        `Failed to upsert shop order with ID ${pickingData.pickingOrderId}:`,
        error,
      );
      throw error; // Optionally rethrow the error for further handling
    }
  }

  public async reschedulingSo(
    writeBackParameters: WriteBackParametersRescheduling,
  ): Promise<WriteBackResponse> {
    const shopOrderId = writeBackParameters.inShopOrder;
    const inNewDate = writeBackParameters.inNewPicking;
    const daprClient = new DaprClient();
    const plantKey = writeBackParameters.inPlant;
    const lockDateTime = new Date().toISOString();
    const shopOrderResponse = await this.getPickingByPlantIdAndShopOrderId(
      plantKey,
      shopOrderId,
    );
    let shopOrder = shopOrderResponse.shopOrderList as ShopOrder;

    if (shopOrder) {
      shopOrder = {
        ...shopOrder,
        lockAction: 'RESCH',
        lockDateTime,
        lockList: ['RESCH', 'CLOSE_SO', 'CREATE_ALERT', 'CLOSE_ALERT'],
      };
    }
    await this.create(plantKey, shopOrder);

    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];

    const parameters = {
      'content-type': 'text/json',
      inNewPicking: inNewDate,
      inPlant: plantKey,
      inShopOrder: shopOrderId,
      inUserName: `${await this.apiManagerConfigService.mesUserName()}`,
      outputParameter: 'ResultXML',
      queryTemplate: 'SC_MES_API/INTERFACE/PICKING/V1/XCT_RESCHEDULE_KANBAN',
      service: 'CombineQueryRowsets',
      session: false,
      xacuteLoginName: `${await this.apiManagerConfigService.mesUserName()}`,
      xacuteLoginPassword: `${mesPasswordValue}`,
    };

    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
      Number(plantKey),
    );
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled(); // Convert the env variable to boolean since its a string

    // If the global variable API_MANAGER_ENABLED is set to true it means
    // We are going to go through api manager else go directly with MII through the plant link coming from PLT HRY Microservice endpoint
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;

    try {
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, undefined, {
          headers: {
            apiKey: apiMgrKeyValue,
          },
          params: parameters,
        }),
      );

      const jsondData = response.data;
      const row = jsondData?.Rowsets?.Rowset[0]?.Row[0];

      if (!row) {
        shopOrder = {
          ...shopOrder,
          lockAction: '',
          lockDateTime: '',
          lockList: [],
        };

        await this.create(plantKey, shopOrder);

        return { statusCode: 'FAILURE', statusMessage: 'Error' };
      }

      const statusCode = row.STATUS_CODE;
      const statusMessage = row.STATUS_MESSAGE;

      if (statusCode !== 'SUCCESS') {
        shopOrder = {
          ...shopOrder,
          lockAction: '',
          lockDateTime: '',
          lockList: [],
        };

        await this.create(plantKey, shopOrder);
      }

      return { statusCode, statusMessage };
    } catch (error) {
      shopOrder = {
        ...shopOrder,
        lockAction: '',
        lockDateTime: '',
        lockList: [],
      };

      await this.create(plantKey, shopOrder);
      return { statusCode: 'FAILURE', statusMessage: error.message };
    }
  }

  public async closeShopOrder(
    writeBackParameters: WriteBackParameters,
  ): Promise<WriteBackResponse> {
    const daprClient = new DaprClient();
    const plantKey = writeBackParameters.inPlant;
    const lockDateTime = new Date().toISOString();
    const shopOrdersIdsArray = writeBackParameters.shopOrderList.split(';');

    shopOrdersIdsArray.forEach(async (element) => {
      try {
        const shopOrderResponse = await this.getPickingByPlantIdAndShopOrderId(
          plantKey,
          element,
        );
        let shopOrder = shopOrderResponse.shopOrderList as ShopOrder;

        if (
          shopOrder &&
          'closeable' in shopOrder &&
          'pickingTime' in shopOrder
        ) {
          if (
            shopOrder.closeable &&
            new Date(shopOrder.pickingTime) < new Date()
          ) {
            shopOrder = {
              ...shopOrder,
              lockAction: 'CLOSE_SO',
              lockDateTime,
              lockList: ['CLOSE_SO', 'CREATE_ALERT', 'RESCH', 'CLOSE_ALERT'],
            };
            await this.create(plantKey, shopOrder);
          } else {
            return {
              statusCode: '500',
              statusMessage:
                'shop order must be closeable and pickingTime inferior to current date',
            };
          }
        }
        return {
          statusCode: '500',
          statusMessage: 'Shop Order not found',
        };
      } catch {
        return {
          statusCode: '500',
          statusMessage: 'An error occurred',
        };
      }
    });

    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];

    // Return shopOrdersArray
    const parameters = {
      'content-type': 'text/json',
      inPlant: plantKey,
      outputParameter: 'ResultXML',
      queryTemplate: 'SC_MES_API/INTERFACE/PICKING/V1/XCT_SO_CLEANSING',
      service: 'CombineQueryRowsets',
      session: false,
      shopOrderList: writeBackParameters.shopOrderList,
      user: 'MES_SYSTEM',
      xacuteLoginName: `${await this.apiManagerConfigService.mesUserName()}`,
      xacuteLoginPassword: `${mesPasswordValue}`,
    };
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
      Number(plantKey),
    );
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled(); // Convert the env variable to boolean since its a string
    // If the global variable API_MANAGER_ENABLED is set to true it means
    // We are going to go through api manager else go directly with MII through the plant link coming from PLT HRY Microservice endpoint
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;

    this.logger.log(`API_MGR_ENABLED : ${isApiManagerEnabled}`);
    this.logger.log(`WriteBack URL : ${writeBackUrl}`);

    try {
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, undefined, {
          headers: {
            apiKey: apiMgrKeyValue,
          },
          params: parameters,
        }),
      );

      const jsonData = response.data;

      if (jsonData?.Rowsets?.Rowset[0]?.Row) {
        const row = jsonData.Rowsets.Rowset[0].Row[0];
        const statusCode = row.STATUS_CODE;
        const statusMessage = row.STATUS_MESSAGE;
        if (statusCode === 'ERROR' || statusCode === '500') {
          this.removeLockInCosmos(shopOrdersIdsArray, plantKey);
        }
        return { statusCode, statusMessage }; // Returning only statusCode and statusMessage
      }
      this.removeLockInCosmos(shopOrdersIdsArray, plantKey);
      return {
        statusCode: 'ERROR',
        statusMessage: 'Enter a valid username and password',
      };
    } catch (error) {
      return { statusCode: '500', statusMessage: error.message };
    }
  }

  public async removeLockInCosmos(
    shopOrdersIdsArray: Array<string>,
    plantKey: string,
  ): Promise<void> {
