  public async getFiltersSelectionsByPlant(
    plant: number,
    screenName: string | undefined,
  ): Promise<FiltersSelectionsDTO> {
    try {
      const fields = [
        'workcenter',
        'sfgWorkcenter',
        'sourceLocation',
        'destinationLocation',
        'customer',
        'outbound',
        'tpaCode',
        'tpaNumber',
        'huCurrentStorageLocation',
      ];
      const fieldsWithDescriptions: Record<string, string> = {
        customer: 'customerDesc',
        workcenter: 'workcenterDescription',
      };
      // Define alertStatus for isAlert true condition
      const alertStatus = ['OPEN', 'Non-Acknowledged'];

      // Helper function to build the query dynamically
      const buildQuery = (field: string): string => {
        let baseQuery = `SELECT DISTINCT VALUE c.${field} 
                         FROM c 
                         WHERE c.plant = @plant 
                           AND IS_DEFINED(c.${field}) 
                           AND c.${field} != null 
                           AND c.${field} != ''`;
        if (field === 'workcenter' || field === 'customer') {
          baseQuery = `SELECT c.${fieldsWithDescriptions[field]}, c.${field}
FROM c
WHERE c.plant = @plant
 AND IS_DEFINED(c.${field}) 
                           AND c.${field} != null 
                           AND c.${field} != ''`;
        }
        if (field === 'sfgWorkcenter') {
          baseQuery = `SELECT DISTINCT VALUE c.sfgWorkcenter
                 FROM c
                 WHERE c.plant = @plant
                   AND IS_DEFINED(c.sfgWorkcenter)
                   AND c.sfgWorkcenter != null
                   AND c.sfgWorkcenter != ''
                   AND c.workcenter != c.sfgWorkcenter`;
        }

        // Add alert status condition for isAlert true
        if (screenName === 'alert') {
          baseQuery += ` AND ARRAY_CONTAINS(@alertStatus, c.alertStatus)`;
        }
        if (field === 'workcenter' || field === 'customer') {
          baseQuery += ` GROUP BY c.${fieldsWithDescriptions[field]}, c.${field}`;
        }
        return baseQuery;
      };

      const workcentersList =
        (await this.plantHYRApi.getWorkcentersListByPlant(Number(plant))) ?? [];

      // Prepare the Cosmos queries (for all fields except material and workcenter)
      const queries = fields
        .filter((field) => field !== 'workcenter')
        .map((field) =>
          this.container.items
            .query({
              parameters: [
                { name: '@plant', value: Number(plant) },
                ...(screenName === 'alert'
                  ? [{ name: '@alertStatus', value: alertStatus }]
                  : []),
              ],
              query: buildQuery(field),
            })
            .fetchAll(),
        );

      // Run all Cosmos queries in parallel
      const results = await Promise.all(queries);

      // Build response object

      const response: Record<string, unknown> = {};
      let resultIndex = 0;

      for (const field of fields) {
        if (field === 'workcenter') {
          response.workcenter = Array.isArray(workcentersList)
            ? workcentersList.map((w: WorkcentersDTO) => ({
                workcenterDescription: w.workcenterDesc, // No description available
                workcenter: w.workcenterId, // Use the string as ID
              }))
            : [];
        } else {
          const queryResult = results[resultIndex];
          resultIndex += 1;

          const values = Array.isArray(queryResult?.resources)
            ? queryResult.resources.map((r: unknown) => r)
            : [];

          response[field] = values;
        }
      }

      return response as unknown as FiltersSelectionsDTO;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve filter selections by plant: ${error.message}`,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve filter selections by plant',
      );
    }
  }

