  public async getOrdersByCriteria(
    plantId: string,
    status?: string,
    queryParameters: PickingQueryParameters = {} as PickingQueryParameters,
    isAlert?: boolean,
  ): Promise<PlantResponse> {
    const adjustedParameters: PickingQueryParameters = { ...queryParameters };
    const filterConditions: Array<string> = [];
    const queryParamter: Array<{
      name: string;
      value: string | number | boolean | Array<string>;
    }> = [];
    // Add status filter if provided
    if (status) {
      filterConditions.push('c.status = @status');
      queryParamter.push({ name: '@status', value: status });
    }

    // Handle pickingStatus and customStatus logic
    if (
      adjustedParameters.pickingStatus &&
      adjustedParameters.pickingStatus.length > 0 &&
      !adjustedParameters.customStatus
    ) {
      adjustedParameters.customStatus = [];
      for (const cstatus of adjustedParameters.pickingStatus) {
        switch (cstatus) {
          case 'IN PRODUCTION': {
            adjustedParameters.customStatus.push(
              'OPEN',
              'PIK_CREATED',
              'PIK_LAUNCHED',
              'PIK_IN_KITTING',
              'PIK_IN_PRODUCTION',
              'SFG_PIK_LAUNCHED',
              'SFG_PIK_KITTING',
              'SFG_PIK_PRODUCTION',
              'SFG_PIK_CLOSED',
            );
            break;
          }
          case 'CLOSED': {
            adjustedParameters.customStatus.push(
              'PICKED',
              'PALLETIZED',
              'PIK_CLOSED',
            );
            break;
          }
          case 'TAKE FROM POOL': {
            adjustedParameters.customStatus.push('TAKE_FROM_STOCK');
            break;
          }
          default: {
            // No custom status for undefined picking statuses
            break;
          }
        }
      }
    }
    // Add isAlert logic
    if (isAlert === true) {
      const alertStatus = ['OPEN', 'Non-Acknowledged'];
      filterConditions.push('ARRAY_CONTAINS(@alertStatus, c.alertStatus)');
      queryParamter.push({ name: '@alertStatus', value: alertStatus });
      const excludedCustomStatuses = ['PIK_CLOSED', 'PICKED', 'PALLETIZED'];
      const excludedStatusesString = excludedCustomStatuses
        .map((s) => `'${s}'`)
        .join(', ');
      filterConditions.push(
        `NOT (c.customStatus IN (${excludedStatusesString}))`,
      );
    }

    addFiltersForQueryParameters(
      adjustedParameters,
      filterConditions,
      queryParamter as Array<{
        name: string;
        value: string | number | boolean;
      }>,
    );
    // Add plant ID to query parameters
    const queryParameterPlant = [
      { name: '@partitionKeyValue', value: Number(plantId) },
    ];
    const allQueryParameters = [...queryParameterPlant, ...queryParamter];

    // Construct query string
    const queryString = `SELECT * FROM c WHERE c.plant = @partitionKeyValue${
      filterConditions.length > 0
        ? ` AND ${filterConditions.join(' AND ')}`
        : ''
    }`;
    try {
      // Fetch data from Cosmos DB
      const { resources: shopOrdersExist } = await this.container.items
        .query({
          parameters: allQueryParameters,
          query: queryString,
        })
        .fetchAll();
      const shopOrdersExists = await this.updateItemsColor(shopOrdersExist);
      return { plantId, shopOrderList: shopOrdersExists };
    } catch (error) {
      this.logger.error(
        `Plant ${plantId} Error fetching data from Cosmos DB: ${error}`,
      );
      throw new HttpException(`Error fetching data from Cosmos DB`, 500);
    }
  }

  public async closeAlert(
    writeBackParameters: WriteBackParameters,
  ): Promise<WriteBackResponse> {
    const { inShopOrder: shopOrderId, inPlant: plantKey } = writeBackParameters;
    const daprClient = new DaprClient();
    const lockDateTime = new Date().toISOString();
    const shopOrderResponse = await this.getPickingByPlantIdAndShopOrderId(
      plantKey,
      shopOrderId,
    );

    let shopOrder = shopOrderResponse.shopOrderList as ShopOrder;
    if (shopOrder) {
      shopOrder = {
        ...shopOrder,
        lockAction: 'CLOSE_ALERT',
        lockDateTime,
        lockList: ['CREATE_ALERT', 'CLOSE_SO', 'RESCH', 'CLOSE_ALERT'],
      };
    }
    await this.create(plantKey, shopOrder);

    const alert = await this.orderApi.getAlertByPlantAndWK(
      Number(plantKey),
      shopOrderId,
    );
    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
      Number(plantKey),
    );

    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled(); // Convert the env variable to boolean since its a string

    const mesUserName = await this.apiManagerConfigService.mesUserName();

    const queryParameters = new URLSearchParams();
    queryParameters.append('service', 'CombineQuery');
    queryParameters.append(
      'queryTemplate',
      'SC_MES_API/INTERFACE/ALERT/V1/UPDATE_ALERT_STATUS_BY_ALERT_ID_PLANT_WK',
    );
    queryParameters.append('InPlant', plantKey);
    queryParameters.append('content-type', 'text/json');
    queryParameters.append('xacuteLoginName', mesUserName);
    queryParameters.append('xacuteLoginPassword', mesPasswordValue);
    queryParameters.append('session', 'false');
    queryParameters.append('Param.1', 'Closed');
    queryParameters.append('Param.2', String(alert.alertId));
    queryParameters.append('Param.3', shopOrderId);
    queryParameters.append('Param.4', plantKey);
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      throw new Error('API Manager setup is incomplete');
    }

    try {
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, undefined, {
          headers: {
            apiKey: apiMgrKeyValue,
          },
          params: queryParameters,
        }),
      );
      const jsondData = response.data;
      const row = jsondData?.Rowsets?.Rowset[0]?.Row[0];
      if (!row) {
        shopOrder = {
          ...shopOrder,
          lockAction: '',
          lockDateTime: '',
          lockList: [],
        };

        await this.create(plantKey, shopOrder);
        return {
          alertId: 0,
          statusCode: 'FAILURE',
          statusMessage: 'Error in MII',
        };
      }
      const { UPDATED_ROW } = row;

      if (UPDATED_ROW === 0) {
        shopOrder = {
          ...shopOrder,
          lockAction: '',
          lockDateTime: '',
          lockList: [],
        };

        await this.create(plantKey, shopOrder);
        return {
          alertId: alert.alertId,
          statusCode: 'FAILURE',
          statusMessage: 'NO_UPDATES',
        };
      }
      return {
        alertId: alert.alertId,
        statusCode: 'SUCCESS',
        statusMessage: 'UPDATED_SUCCESSFULY',
      };
    } catch (error) {
      shopOrder = {
        ...shopOrder,
        lockAction: '',
        lockDateTime: '',
        lockList: [],
      };

      await this.create(plantKey, shopOrder);
      if (error.response) {
        // Handle HTTP errors
        switch (error.response.status) {
          case 404: {
            this.logger.error(
              `Resource not found (404). URL: ${error.config.url}`,
            );
            throw new Error('Resource not found (404)');
          }
          case 500: {
            this.logger.error(
              `Internal Server Error (500). URL: ${error.config.url}`,
            );
            throw new Error('Internal Server Error (500)');
          }
          default: {
            this.logger.error(
              `Unexpected HTTP error: ${error.response.status}. URL: ${error.config.url}`,
            );
            throw new Error(
              `Unexpected error occurred: ${error.response.status}`,
            );
          }
        }
      } else {
        this.logger.error('An unexpected error occurred', error);
        throw new Error('An unexpected error occurred');
      }
    }
  }

