  private updateColorAttribute(item: ShopOrder): string {
    try {
      const currentDate = Date.now();
      if (item.truckDepartureTime && validateDate(item.truckDepartureTime)) {
        const truckDepartureTime = new Date(item.truckDepartureTime).getTime();
        if (item.newPromiseTime && validateDate(item.newPromiseTime)) {
          const newPromiseTime = new Date(item.newPromiseTime).getTime();
          if (newPromiseTime > truckDepartureTime) {
            return 'RED';
          }
        }
        if (currentDate > truckDepartureTime) {
          return 'RED';
        }
        const tpaEndPreparationCheck = tpaEndPreparationChecks(
          item,
          truckDepartureTime,
          currentDate,
        );
        if (tpaEndPreparationCheck) {
          return tpaEndPreparationCheck;
        }
      }
      if (item.pickingTime && validateDate(item.pickingTime)) {
        return whiteOrGreyCheck(item, currentDate);
      }
      return '';
    } catch (error) {
      this.logger.error(
        `error in updateColorAttribute  for plant ${item?.plantId} and wk ${item?.pickingOrderId} `,
        error,
      );
      return '';
    }
  }

