  public async getComment(
    pickingOrderId: string,
    plant: number,
    userId: number,
  ): Promise<Array<PickingOrderComment>> {
    const daprClient = new DaprClient();
    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const response = (await daprClient.invoker.invoke(
        this.apiManagerConfigService.orderApiAppId,
        `picking-order-comments/${plant}/${pickingOrderId}/${userId}`,
        HttpMethod.GET,
        undefined,
        options,
      )) as Array<PickingOrderComment>;
      if (!response || response.length === 0) {
        this.logger.error('Comments not found.');
        return [];
      }

      const usersInfo = await this.getUserByPlant(plant);
      for (const comment of response) {
        const user = usersInfo.find((user) => user.userId === comment.userId);
        if (comment.userId === 0) {
          // Special SYSTEM user
          comment.firstName = 'SYSTEM';
          comment.lastName = '';
        } else if (user) {
          comment.firstName = user.firstName;
          comment.lastName = user.lastName;
        } else {
          this.logger.error(
            `User with ID ${comment.userId} not found for plant ${plant}`,
          );
        }
      }

      return response;
    } catch (error) {
      this.logger.error(
        'Error invoking Dapr service to fetch comments:',
        error,
      );
      throw error;
    }
  }

