  public async createAlert(
    writeBackParameters: WriteBackParameters,
  ): Promise<Array<WriteBackResponse>> {
    const { inPlant: plantKey } = writeBackParameters;
    const shopOrdersIdsArray = writeBackParameters.shopOrderList.split(';');
    const responseArray: Array<WriteBackResponse> = [];
    const daprClient = new DaprClient();
    const lockDateTime = new Date().toISOString();
    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
      Number(plantKey),
    );

    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      throw new Error('API Manager setup is incomplete');
    }
    const responseBack = new WriteBackResponse();
    const root = create().ele('Rowsets');
    const rowset = root.ele('Rowset');
    try {
      let shopOrders = await this.getPickingByPlantIdAndShopOrderIds(
        plantKey,
        shopOrdersIdsArray,
      );
      const foundShopOrderIds = new Set(
        shopOrders.map((order) => order?.pickingOrderId),
      );
      shopOrders = await updateWorkcentersForSfgUseCase(
        plantKey,
        shopOrders,
        this.orderApi,
      );
      const workcenters = shopOrders.map((order) => order?.workcenter);
      const missingShopOrders = shopOrdersIdsArray.filter(
        (id) => !foundShopOrderIds.has(id),
      );

      if (missingShopOrders.length > 0) {
        for (const missingId of missingShopOrders) {
          responseArray.push({
            alertId: 0,
            statusCode: 'FAILURE',
            statusMessage: `ShopOrder ${missingId} not found.`,
          });
        }
        return responseArray;
      }
      const alertConfigIds =
        await this.orderApi.getAlertConfigByPlantAndWorkcenters(
          Number(plantKey),
          workcenters,
        );
      if (!alertConfigIds) {
        responseBack.alertId = 0;
        responseBack.statusCode = 'FAILURE';
        responseBack.statusMessage = 'Alert configuration not found.';
        responseArray.push(responseBack);
        return responseArray;
      }
      const resources = (await this.plantHYRApi.getResourceDetailsByWcIds(
        Number(plantKey),
        workcenters,
      )) as Record<string, ResourceResponseDTO>;

      const newshopOrder = [];
      let resource = '';
      for (const shopOrder of shopOrders) {
        if (resources) {
          resource = resources[shopOrder.workcenter]?.resourceId || '';
        }

        const validation = createAlertValidation(shopOrder, alertConfigIds);
        if (validation) {
          return validation;
        }
        newshopOrder.push({
          ...shopOrder,
          lockAction: 'CREATE_ALERT',
          lockDateTime,
          lockList: ['CREATE_ALERT', 'CLOSE_SO', 'RESCH', 'CLOSE_ALERT'],
        });
        const row = rowset.ele('Row');
        row
          .ele('ALERT_CONFIG_ID')
          .txt(String(alertConfigIds[shopOrder.workcenter].alertConfigId));
        row.ele('MATERIAL').txt(shopOrder.material);
        row.ele('PICKING_ORDER_ID').txt(shopOrder.pickingOrderId);
        row.ele('WORKCENTER').txt(shopOrder.workcenter);
        row.ele('RESOURCE_ID').txt(resource);
        row.ele('ALERT_SOURCE').txt('MANUAL');
        root.end({ prettyPrint: true });
      }
      await Promise.all(
        newshopOrder.map((order) => this.create(plantKey, order)),
      );
      return await this.handleCreateAlertRequest(
        plantKey,
        root,
        apiMgrKeyValue,
        mesPasswordValue,
        writeBackUrl,
        shopOrdersIdsArray,
        responseArray,
      );
    } catch (error) {
      console.error('Error fetching Shop Orders:', error);
      responseArray.push({
        alertId: 0,
        statusCode: 'FAILURE',
        statusMessage: 'An error occurred while retrieving Shop Orders.',
      });
      return responseArray;
    }
  }

  private async handleCreateAlertRequest(
    plantKey: string,
    root: XMLBuilder,
    apiMgrKeyValue: string,
    mesPasswordValue: string,
    writeBackUrl: string,
    shopOrdersIdsArray: Array<string>,
    responseArray: Array<WriteBackResponse>,
  ): Promise<Array<WriteBackResponse>> {
    try {
      const formData = new URLSearchParams();
      formData.append('listWksXml', root.toString());
      const headersDto = new RequestHeadersDto(
        'application/x-www-form-urlencoded',
        apiMgrKeyValue,
      );
      const parameters = new AlertConfigRequestDto(
        Number(plantKey),
        'text/json',
        'ResultXML',
        'SC_MES_API/INTERFACE/ALERT/V1/XCT_CREATE_ALERT',
        false,
        `${await this.apiManagerConfigService.mesUserName()}`,
        `${mesPasswordValue}`,
      );
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, formData, {
          headers: { ...headersDto },
          params: parameters,
        }),
      );
      const jsonData = response.data;
      const rows = jsonData?.Rowsets?.Rowset[0]?.Row;
      for (const item of rows) {
        const writeBackResponse = new WriteBackResponse();
        writeBackResponse.alertId = item['ALERT_ID'];
        writeBackResponse.pickingOrderId = item['PICKING_ORDER_ID'];
        writeBackResponse.statusCode = item['STATUS_CODE'];
        writeBackResponse.statusMessage = item['STATUS_MESSAGE'];
        responseArray.push(writeBackResponse);
      }
      this.removeLockInCosmos(shopOrdersIdsArray, plantKey);
      return responseArray;
    } catch (error) {
      this.removeLockInCosmos(shopOrdersIdsArray, plantKey);
      if (error.response) {
        // Handle HTTP errors
        switch (error.response.status) {
          case 404: {
            this.logger.error(
              `Resource not found (404). URL: ${error.config.url}`,
            );
            throw new Error('Resource not found (404)');
          }
          case 500: {
            this.logger.error(
              `Internal Server Error (500). URL: ${error.config.url}`,
            );
            throw new Error('Internal Server Error (500)');
          }
          default: {
            this.logger.error(
              `Unexpected HTTP error: ${error.response.status}. URL: ${error.config.url}`,
            );
            throw new Error(
              `Unexpected error occurred: ${error.response.status}`,
            );
          }
        }
      } else {
        this.logger.error('An unexpected error occurred', error);
        throw new Error('An unexpected error occurred');
      }
    }
  }
}

